import { promises as fs } from "node:fs";
import path from "node:path";
import { z } from "zod";
import { localModel, type LocalSpeechModel, type ModelPrecision } from "./local-models";

export type ModelFamily = "whisper" | "moonshine";
export type ModelFolder = { folder: string; family: ModelFamily; dtype: ModelPrecision };

const ONNX_RUNTIME_PLATFORMS = ["win32-x64", "win32-arm64", "linux-x64", "linux-arm64", "darwin-arm64"];
export const localSpeechSupported = () => ONNX_RUNTIME_PLATFORMS.includes(`${process.platform}-${process.arch}`);

export const speechModelsDir = () => path.join(process.env.MONEO_DATA_DIR ?? path.join(/*turbopackIgnore: true*/ process.cwd(), ".data"), "speech-models");
export const modelFolder = (model: Pick<LocalSpeechModel, "id">, dir = speechModelsDir()) => path.join(dir, model.id);

const size = (file: string) => fs.stat(file).then(stat => stat.isFile() ? stat.size : -1, () => -1);

export async function isInstalled(model: LocalSpeechModel, dir = speechModelsDir()) {
  const sizes = await Promise.all(model.files.map(file => size(path.join(modelFolder(model, dir), file.path))));
  return sizes.every((bytes, index) => bytes === model.files[index].bytes);
}

const configSchema = z.object({ model_type: z.enum(["whisper", "moonshine"]) });
const SUFFIX: Record<ModelPrecision, string> = { q8: "_quantized", fp32: "", fp16: "_fp16" };
const REQUIRED = ["tokenizer.json", "tokenizer_config.json", "preprocessor_config.json", "generation_config.json"];

export async function inspectFolder(folder: string): Promise<ModelFolder | null> {
  const config = configSchema.safeParse(await fs.readFile(path.join(folder, "config.json"), "utf8").then(JSON.parse).catch(() => null));
  if (!config.success) return null;
  if ((await Promise.all(REQUIRED.map(file => size(path.join(folder, file))))).some(bytes => bytes <= 0)) return null;
  for (const dtype of Object.keys(SUFFIX) as ModelPrecision[]) {
    const parts = ["encoder_model", "decoder_model_merged"].map(part => path.join(folder, "onnx", `${part}${SUFFIX[dtype]}.onnx`));
    if ((await Promise.all(parts.map(size))).every(bytes => bytes > 0)) return { folder, family: config.data.model_type, dtype };
  }
  return null;
}

export async function resolveModel(ref: string | null, dir = speechModelsDir()): Promise<ModelFolder | null> {
  if (!ref) return null;
  const known = localModel(ref);
  if (known) return await isInstalled(known, dir) ? inspectFolder(modelFolder(known, dir)) : null;
  return path.isAbsolute(ref) ? inspectFolder(ref) : null;
}

import { createHash } from "node:crypto";
import { createReadStream, promises as fs } from "node:fs";
import path from "node:path";
import type { LocalSpeechModel, ModelFile } from "./local-models";
import { isInstalled, modelFolder, speechModelsDir } from "./model-store";

export type DownloadStatus =
  | { state: "missing" }
  | { state: "downloading"; received: number; total: number }
  | { state: "installed" }
  | { state: "failed"; error: string; received: number; total: number };

type Progress = { received: number; total: number; error?: string };

const fileUrl = (model: LocalSpeechModel, file: ModelFile) => `https://huggingface.co/${model.repo}/resolve/${model.revision}/${file.path}`;
const size = (file: string) => fs.stat(file).then(stat => stat.size, () => 0);

async function matches(file: string, expected: ModelFile) {
  if (await size(file) !== expected.bytes) return false;
  const hash = "sha256" in expected ? createHash("sha256") : createHash("sha1").update(`blob ${expected.bytes}\0`);
  for await (const chunk of createReadStream(file)) hash.update(chunk as Buffer);
  return hash.digest("hex") === ("sha256" in expected ? expected.sha256 : expected.gitSha1);
}

export function createModelDownloads({ dir = speechModelsDir, fetcher = (url: string, init: RequestInit) => fetch(url, init) }: {
  dir?: () => string; fetcher?: (url: string, init: RequestInit) => Promise<Response>;
} = {}) {
  const progress = new Map<string, Progress>();
  const running = new Map<string, Promise<void>>();

  async function fetchFile(model: LocalSpeechModel, file: ModelFile, counter: Progress) {
    const target = path.join(modelFolder(model, dir()), file.path), part = `${target}.part`;
    if (await size(target) === file.bytes) return;
    await fs.mkdir(path.dirname(target), { recursive: true });
    let have = await size(part);
    if (have > file.bytes) { await fs.rm(part, { force: true }); have = 0; }
    counter.received += have;
    if (have < file.bytes) {
      const response = await fetcher(fileUrl(model, file), { headers: have ? { Range: `bytes=${have}-` } : {}, signal: AbortSignal.timeout(30 * 60_000) });
      if (!response.ok || !response.body) throw new Error(`The download server answered ${response.status}`);
      const resumed = have > 0 && response.status === 206;
      if (!resumed) { counter.received -= have; have = 0; }
      const handle = await fs.open(part, resumed ? "a" : "w");
      try {
        for await (const chunk of response.body) { await handle.write(chunk); counter.received += chunk.byteLength; }
      } finally { await handle.close(); }
    }
    if (!await matches(part, file)) {
      await fs.rm(part, { force: true });
      throw new Error(`${file.path} did not match the expected file. Try the download again.`);
    }
    await fs.rename(part, target);
  }

  async function download(model: LocalSpeechModel) {
    const counter: Progress = { received: 0, total: model.files.reduce((total, file) => total + file.bytes, 0) };
    progress.set(model.id, counter);
    try {
      for (const file of model.files) await fetchFile(model, file, counter);
      progress.delete(model.id);
    } catch (cause) {
      counter.error = cause instanceof Error ? cause.message : "The download failed";
      console.warn("[speech] model-download-failed", model.id);
    }
  }

  return {
    start(model: LocalSpeechModel) {
      const existing = running.get(model.id);
      if (existing) return existing;
      const job = download(model).finally(() => running.delete(model.id));
      running.set(model.id, job);
      return job;
    },
    async status(model: LocalSpeechModel): Promise<DownloadStatus> {
      const current = progress.get(model.id);
      if (current?.error) return { state: "failed", error: current.error, received: current.received, total: current.total };
      if (current) return { state: "downloading", received: current.received, total: current.total };
      return await isInstalled(model, dir()) ? { state: "installed" } : { state: "missing" };
    },
  };
}

export const modelDownloads = createModelDownloads();

import path from "node:path";
import { parentPort } from "node:worker_threads";

const SAMPLE_RATE = 16000;
const WINDOW_SECONDS = 30;
const MAX_PROMPT_TOKENS = 200;
const WHISPER_MAX_TOKENS = 448;

let loaded = null;

async function load({ folder, dtype }) {
  const key = `${folder}\n${dtype}`;
  if (loaded?.key === key) return loaded;
  await loaded?.model.dispose();
  loaded = null;
  const { AutoModelForSpeechSeq2Seq, AutoProcessor, env } = await import("@huggingface/transformers");
  env.allowRemoteModels = false;
  env.allowLocalModels = true;
  env.useFSCache = false;
  env.localModelPath = `${path.dirname(folder)}${path.sep}`;
  const id = path.basename(folder);
  const [processor, model] = await Promise.all([
    AutoProcessor.from_pretrained(id, { local_files_only: true }),
    AutoModelForSpeechSeq2Seq.from_pretrained(id, { local_files_only: true, dtype, device: "cpu" }),
  ]);
  loaded = { key, processor, model, tokenizer: processor.tokenizer };
  return loaded;
}

const lastToken = REDACTED => Number(output.tolist()[0].at(-1));

async function whisper({ processor, model, tokenizer }, samples, prompt) {
  const config = model.generation_config;
  const { input_features } = await processor(samples);
  const promptIds = prompt && config.prev_sot_token_id ? tokenizer.encode(` ${prompt}`, { add_special_tokens: false }).slice(-MAX_PROMPT_TOKENS) : [];
  const start = [...(promptIds.length ? [config.prev_sot_token_id, ...promptIds] : []), config.decoder_start_token_id];
  if (config.is_multilingual) {
    const language = lastToken(await model.generate({ inputs: input_features, decoder_input_ids: start, max_new_tokens: 1 }));
    const languages = new Set(Object.values(config.lang_to_id));
    start.push(languages.has(language) ? language : config.lang_to_id["<|en|>"], config.task_to_id.transcribe);
  }
  start.push(config.no_timestamps_token_id);
  const output = await model.generate({ inputs: input_features, decoder_input_ids: start, max_new_tokens: WHISPER_MAX_TOKENS - start.length - 1 });
  return tokenizer.decode(output.tolist()[0].slice(start.length), { skip_special_tokens: true });
}

async function moonshine({ processor, model, tokenizer }, samples) {
  const inputs = await processor(samples);
  const output = await model.generate({ ...inputs, max_new_tokens: Math.ceil(samples.length / SAMPLE_RATE) * 6 + 8 });
  return tokenizer.batch_decode(output, { skip_special_tokens: true })[0];
}

async function transcribe({ folder, family, dtype, samples, prompt }) {
  const runtime = await load({ folder, dtype });
  const window = SAMPLE_RATE * WINDOW_SECONDS;
  const texts = [];
  for (let offset = 0; offset < samples.length; offset += window) {
    const chunk = samples.subarray(offset, offset + window);
    texts.push(family === "whisper" ? await whisper(runtime, chunk, prompt) : await moonshine(runtime, chunk));
  }
  return texts.map(text => text.trim()).filter(Boolean).join(" ");
}

parentPort?.on("message", async ({ id, job }) => {
  try { parentPort?.postMessage({ id, text: await transcribe(job) }); }
  catch (cause) { parentPort?.postMessage({ id, error: cause instanceof Error ? cause.message : String(cause) }); }
});

import { Worker } from "node:worker_threads";
import type { SpeechModelJob, SpeechModelRunner } from "./local";

const IDLE_UNLOAD_MS = 5 * 60_000;
type Pending = { resolve: (text: string) => void; reject: (error: Error) => void };
type Reply = { id: number; text?: string; error?: string };

export function createWorkerRunner(spawn: () => Worker, idleMs = IDLE_UNLOAD_MS): SpeechModelRunner {
  let worker: Worker | undefined, idle: NodeJS.Timeout | undefined, nextId = 0;
  const pending = new Map<number, Pending>();

  const stop = () => { const current = worker; worker = undefined; void current?.terminate(); };
  const failAll = (error: Error) => { for (const job of pending.values()) job.reject(error); pending.clear(); };
  const scheduleUnload = () => { clearTimeout(idle); if (!pending.size) idle = setTimeout(stop, idleMs).unref(); };

  function running() {
    if (worker) return worker;
    const started = spawn();
    started.on("message", ({ id, text, error }: Reply) => {
      const job = pending.get(id);
      if (!job) return;
      pending.delete(id);
      if (typeof text === "string") job.resolve(text); else job.reject(new Error(error ?? "The speech model failed"));
      scheduleUnload();
    });
    started.on("error", error => { if (worker === started) worker = undefined; failAll(error); });
    started.on("exit", () => { if (worker === started) worker = undefined; failAll(new Error("The speech model stopped")); });
    worker = started;
    return started;
  }

  return {
    transcribe(job: SpeechModelJob) {
      clearTimeout(idle);
      const id = nextId++;
      return new Promise<string>((resolve, reject) => {
        pending.set(id, { resolve, reject });
        running().postMessage({ id, job }, [job.samples.buffer as ArrayBuffer]);
      });
    },
  };
}

export const workerRunner = createWorkerRunner(() => new Worker(new URL("./local-worker.mjs", import.meta.url)));

import type { BatchSpeechEngine, SpeechAudio, SpeechHints } from "./engine";
import { promptWithNames } from "./hints";
import { localSpeechSupported, resolveModel, type ModelFolder } from "./model-store";

const MODEL_RATE = 16000;

export type SpeechModelJob = ModelFolder & { samples: Float32Array; prompt: string };
export type SpeechModelRunner = { transcribe: (job: SpeechModelJob) => Promise<string> };

export function modelSamples({ samples, sampleRate }: SpeechAudio) {
  const length = Math.floor(samples.length * MODEL_RATE / sampleRate);
  const output = new Float32Array(length);
  for (let index = 0; index < length; index++) {
    const position = index * sampleRate / MODEL_RATE, before = Math.floor(position);
    const after = Math.min(before + 1, samples.length - 1);
    output[index] = (samples[before] + (samples[after] - samples[before]) * (position - before)) / 0x8000;
  }
  return output;
}

export async function transcribeLocally(ref: string | null, runner: SpeechModelRunner, audio: SpeechAudio, hints: SpeechHints) {
  const model = await resolveModel(ref);
  if (!model) throw new Error("The speech model is missing. Download it or choose its folder again.");
  return runner.transcribe({ ...model, samples: modelSamples(audio), prompt: promptWithNames(hints) });
}

export const localSpeech = (ref: string | null, runner: SpeechModelRunner): BatchSpeechEngine => ({
  available: async () => localSpeechSupported() && Boolean(await resolveModel(ref)),
  transcribe: (audio, hints) => transcribeLocally(ref, runner, audio, hints),
});

