    if (status.state === "downloading") console.log(`downloading ${Math.round(status.received / 1e6)} of ${Math.round(status.total / 1e6)} MB`);
  }, 5000);
  await job;
  clearInterval(timer);
  const status = await modelDownloads.status(model);
