import type { Worker } from "node:worker_threads";
import { afterEach, beforeEach, expect, it, vi } from "vitest";
import { createWorkerRunner } from "./local-runner";

class FakeWorker extends EventEmitter {
  jobs: { id: number }[] = [];
  terminate = vi.fn(async () => 0);
